    sha256: "d21291c281604ccc6272c81c6506c8d521bc38d3141b0d339cb1a5988b1d461d",
  },
  storage: {
    version: "v1.88.0", commit: "327681449182ade2f9173c968dd8e8ee3c9888fd", license: "Apache-2.0",
