// The bundled PostgreSQL cluster: initdb on first run, start and stop through pg_ctl (which on
// Windows also drops administrator rights, as postgres.exe requires), stale postmaster.pid recovery.
import { existsSync } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import { exe, isAlive, mustRun, processName, runProgram } from "./processes";

export type Cluster = { bin: string; data: string; logs: string; port: number; password: string };

const program = (cluster: Pick<Cluster, "bin">, name: string) => path.join(cluster.bin, `${name}${exe}`);

export const isInitialized = (data: string) => existsSync(path.join(data, "PG_VERSION"));

export async function bundledMajor(bin: string) {
  const output = await mustRun(program({ bin }, "postgres"), ["--version"]);
  const major = output.match(/PostgreSQL\)\s+(\d+)/)?.[1];
  if (!major) throw new Error(`Could not read the bundled PostgreSQL version from "${output.trim()}"`);
  return major;
}

// The cluster's major version must match the bundled server; a major upgrade needs pg_upgrade.
export async function checkMajor(cluster: Cluster) {
  const data = (await fs.readFile(path.join(cluster.data, "PG_VERSION"), "utf8")).trim();
  const bundled = await bundledMajor(cluster.bin);
  if (data !== bundled) throw new Error(`The database was created by PostgreSQL ${data}, but this Moneo bundles PostgreSQL ${bundled}. Install the matching Moneo version or restore a backup.`);
}

// Like the Supabase image: UTF8, ICU collation en-US, scram-sha-256, superuser supabase_admin with
// POSTGRES_PASSWORD. Only TCP connections from 127.0.0.1 are accepted.
export async function initCluster(cluster: Cluster, home: string) {
  await fs.mkdir(path.dirname(cluster.data), { recursive: true });
  const pwfile = path.join(home, `.initdb-${process.pid}`);
  await fs.writeFile(pwfile, cluster.password, { mode: 0o600 });
  try {
    // libc locale for messages and number formats; ICU decides collation. Windows names it en-US,
    // macOS/Linux en_US.UTF-8, with C.UTF-8 and C as fallbacks on minimal Linux systems.
    const locales = process.platform === "win32" ? ["en-US"] : ["en_US.UTF-8", "C.UTF-8", "C"];
    let failure = "";
    for (const locale of locales) {
      await fs.rm(cluster.data, { recursive: true, force: true });
      const result = await runProgram(program(cluster, "initdb"), ["-D", cluster.data, "-U", "supabase_admin", `--pwfile=${pwfile}`,
        "--auth=scram-sha-256", "-E", "UTF8", "--locale-provider=icu", "--icu-locale=en-US", `--locale=${locale}`], { timeoutMs: 180_000 });
      if (result.code === 0) { failure = ""; break; }
      failure = result.output;
    }
    if (failure) throw new Error(`initdb failed:\n${failure.trim()}`);
  } finally {
    await fs.rm(pwfile, { force: true });
  }
  await fs.writeFile(path.join(cluster.data, "pg_hba.conf"),
    "# Moneo Desktop: password logins over TCP from this computer only; no Unix sockets.\n" +
    "# TYPE  DATABASE  USER  ADDRESS       METHOD\nhost    all       all   127.0.0.1/32  scram-sha-256\n");
  const conf = path.join(cluster.data, "postgresql.conf");
  await fs.appendFile(conf, "\n# Moneo Desktop settings, rewritten at every start.\ninclude 'moneo.conf'\n");
}

// Settings that differ from initdb's defaults. The Supabase image's values are kept where they
// change query results (UTC, extra_float_digits = 0, row_security, english text search).
async function writeSettings(cluster: Cluster) {
  const logs = cluster.logs.replaceAll("\\", "/").replaceAll("'", "''");
  await fs.writeFile(path.join(cluster.data, "moneo.conf"), [
    "listen_addresses = '127.0.0.1'",
    `port = ${cluster.port}`,
    "unix_socket_directories = ''",
    "password_encryption = scram-sha-256",
    "timezone = 'UTC'",
    "log_timezone = 'UTC'",
    "datestyle = 'iso, mdy'",
    "row_security = on",
    "extra_float_digits = 0",
    "default_text_search_config = 'pg_catalog.english'",
    "jit = off",
    "logging_collector = on",
    `log_directory = '${logs}'`,
    "log_filename = 'postgres-%a.log'",
    "log_truncate_on_rotation = on",
    "log_rotation_age = 1d",
    "log_rotation_size = 0",
    "log_line_prefix = '%m [%p] %q%u@%d '",
    "",
  ].join("\n"));
}

async function postmasterPid(data: string) {
  const text = await fs.readFile(path.join(data, "postmaster.pid"), "utf8").catch(() => "");
  const pid = Number(text.split("\n")[0]);
  return Number.isInteger(pid) && pid > 0 ? pid : undefined;
}

// A postmaster.pid left by a crash: stop the server if it is still ours, delete the file if the
// process is gone or the PID now belongs to another program (postgres would refuse to start).
async function recoverStalePid(cluster: Cluster, log: (line: string) => void) {
  const pid = await postmasterPid(cluster.data);
  if (!pid) return;
  const name = await processName(pid);
  if (name === `postgres${exe}`) {
    log(`PostgreSQL (pid ${pid}) is still running from an earlier session; restarting it`);
    await stopCluster(cluster);
  } else {
    log(`Removing stale postmaster.pid (pid ${pid} is ${name ? `now ${name}` : "gone"})`);
    await fs.rm(path.join(cluster.data, "postmaster.pid"), { force: true });
  }
}

export async function startCluster(cluster: Cluster, log: (line: string) => void) {
  await fs.mkdir(cluster.logs, { recursive: true });
  await recoverStalePid(cluster, log);
  await writeSettings(cluster);
  const { code, output } = await runProgram(program(cluster, "pg_ctl"),
    ["start", "-D", cluster.data, "-w", "-t", "120", "-l", path.join(cluster.logs, "postgres-start.log")], { timeoutMs: 150_000 });
  if (code !== 0) {
    const startLog = await fs.readFile(path.join(cluster.logs, "postgres-start.log"), "utf8").catch(() => "");
    throw new Error(`PostgreSQL did not start (pg_ctl exit ${code}):\n${output.trim()}\n${startLog.split("\n").slice(-15).join("\n")}`);
  }
  const pid = await postmasterPid(cluster.data);
  if (!pid) throw new Error("PostgreSQL started but wrote no postmaster.pid");
  return pid;
}

export async function stopCluster(cluster: Pick<Cluster, "bin" | "data">) {
  if (!(await postmasterPid(cluster.data))) return;
  const { code, output } = await runProgram(program(cluster, "pg_ctl"), ["stop", "-D", cluster.data, "-m", "fast", "-w", "-t", "60"], { timeoutMs: 90_000 });
  // pg_ctl exits 1 with "PID file ... does not exist" / "Is server running?" when it already stopped.
  if (code !== 0 && !/does not exist|not running/i.test(output)) throw new Error(`pg_ctl stop failed (exit ${code}): ${output.trim()}`);
}

export async function runningPid(data: string) {
  const pid = await postmasterPid(data);
  return pid && isAlive(pid) ? pid : undefined;
}

export const pgProgram = program;

// The one Supabase URL the app talks to, replacing docker/Caddyfile: /auth/v1 → GoTrue,
// /rest/v1 → PostgREST, /storage/v1 → Storage, with the prefix stripped. Bodies stream both ways.
import http from "node:http";
import type { AddressInfo } from "node:net";

export type Routes = { auth: number; rest: number; storage: number };

const PREFIXES: [string, keyof Routes][] = [["/auth/v1", "auth"], ["/rest/v1", "rest"], ["/storage/v1", "storage"]];
const HOP_BY_HOP = ["connection", "keep-alive", "proxy-connection", "proxy-authenticate", "proxy-authorization", "te", "trailer", "upgrade"];

export function startGateway(port: number, routes: Routes, log: (line: string) => void) {
  const agent = new http.Agent({ keepAlive: true, maxSockets: 64 });
  const server = http.createServer((req, res) => {
    const url = req.url ?? "/";
    const match = PREFIXES.find(([prefix]) => url === prefix || url.startsWith(`${prefix}/`) || url.startsWith(`${prefix}?`));
    if (!match) { res.writeHead(404).end(); return; }
    const [prefix, service] = match;
    const headers: http.OutgoingHttpHeaders = { ...req.headers };
    for (const name of HOP_BY_HOP) delete headers[name];
    const forwarded = req.headers["x-forwarded-for"];
    headers["x-forwarded-for"] = forwarded ? `${forwarded}, ${req.socket.remoteAddress}` : req.socket.remoteAddress;
    headers["x-forwarded-proto"] ??= "http";
    headers["x-forwarded-host"] ??= req.headers.host;
    const upstream = http.request({ host: "127.0.0.1", port: routes[service], method: req.method, path: url.slice(prefix.length) || "/", headers, agent }, upstreamRes => {
      const responseHeaders = { ...upstreamRes.headers };
      for (const name of HOP_BY_HOP) delete responseHeaders[name];
      res.writeHead(upstreamRes.statusCode ?? 502, upstreamRes.statusMessage, responseHeaders);
      upstreamRes.pipe(res);
      upstreamRes.once("error", () => res.destroy());
    });
    upstream.once("error", error => {
      if (!res.headersSent) res.writeHead(502, { "content-type": "application/json" }).end(JSON.stringify({ message: `${service} is not reachable`, error: error.message }));
      else res.destroy();
    });
    res.once("close", () => { if (!res.writableFinished) upstream.destroy(); });
    req.pipe(upstream);
  });
  // Uploads up to Storage's 50 MB limit can take a while on slow disks.
  server.requestTimeout = 0;
  return new Promise<{ port: number; close(): Promise<void> }>((resolve, reject) => {
    server.once("error", reject);
    server.listen({ host: "127.0.0.1", port, exclusive: true }, () => {
      log(`Gateway listening on 127.0.0.1:${(server.address() as AddressInfo).port}`);
      resolve({
        port: (server.address() as AddressInfo).port,
        close: () => new Promise<void>(done => { server.close(() => done()); server.closeAllConnections(); agent.destroy(); }),
      });
    });
  });
}

// Database setup: the Supabase-image bootstrap (desktop/bootstrap), Moneo's supabase/migrations
// applied exactly like scripts/setup.mjs, and the owner account.
import { readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import postgres from "postgres";

export type Db = ReturnType<typeof postgres>;

export function connect(port: number, user: string, password: string, database = "postgres"): Db {
  return postgres({ host: "127.0.0.1", port, user, password, database, max: 1, onnotice: () => {}, connect_timeout: 10 });
}

const literal = (value: string) => `'${value.replaceAll("'", "''")}'`;

// Passwords and JWT settings, the values docker/db/roles.sql sets in the Docker backend.
export async function applyRoleSecrets(db: Db, password: string, jwtSecret: string) {
  for (const role of ["supabase_admin", "postgres", "authenticator", "supabase_auth_admin", "supabase_storage_admin"])
    await db.unsafe(`alter role ${role} with password ${literal(password)}`);
  await db.unsafe(`alter database postgres set "app.settings.jwt_secret" to ${literal(jwtSecret)}`);
  await db.unsafe(`alter database postgres set "app.settings.jwt_exp" to '3600'`);
}

// files: the bootstrap SQL to run (all of them on a fresh cluster; only roles before a restore).
export async function bootstrap(db: Db, folder: string, files: string[], password: string, jwtSecret: string) {
  for (const file of files) {
    const sql = readFileSync(path.join(folder, file), "utf8");
    await db.begin(tx => tx.unsafe(sql));
  }
  await applyRoleSecrets(db, password, jwtSecret);
}

export const bootstrapFiles = (folder: string) => readdirSync(folder).filter(file => file.endsWith(".sql")).sort();

export type MigrationFile = { file: string; version: string };

export function bundledMigrations(folder: string): MigrationFile[] {
  return readdirSync(folder).filter(file => file.endsWith(".sql")).sort().map(file => ({ file, version: file.split("_")[0] }));
}

// Same history table as the Supabase CLI and scripts/setup.mjs.
export async function migrationState(db: Db, bundled: MigrationFile[]) {
  await db`create schema if not exists supabase_migrations`;
  await db`create table if not exists supabase_migrations.schema_migrations (version text primary key, statements text[], name text)`;
  const applied = (await db<{ version: string }[]>`select version from supabase_migrations.schema_migrations`).map(row => row.version);
  const latest = bundled.at(-1)?.version ?? "";
  const newer = applied.filter(version => version > latest).sort();
  const known = new Set(applied);
  return { applied, newer, pending: bundled.filter(migration => !known.has(migration.version)) };
}

// supautils, which the Supabase image loads and Moneo does not bundle, lets postgres create and drop
// policies and triggers on the auth.* and storage.* tables (supautils.policy_grants /
// drop_trigger_grants). Without it the same statements need ownership, so during Moneo's own
// migrations postgres inherits the two owner roles, and loses them again right after.
const OWNERS = ["supabase_auth_admin", "supabase_storage_admin"];
export async function revokeMigrationOwners(admin: Db) {
  for (const role of OWNERS) await admin.unsafe(`revoke ${role} from postgres`);
}

export async function applyMigrations(admin: Db, owner: Db, folder: string, pending: MigrationFile[], log: (line: string) => void) {
  if (!pending.length) return 0;
  for (const role of OWNERS) await admin.unsafe(`grant ${role} to postgres with inherit true, set false`);
  try {
    for (const { file, version } of pending) {
      const source = readFileSync(path.join(folder, file), "utf8");
      await owner.begin(async tx => {
        await tx.unsafe(source);
        await tx`insert into supabase_migrations.schema_migrations (version, name, statements) values (${version}, ${file.slice(version.length + 1, -4)}, ${[source]})`;
      });
      log(`Applied migration ${file}`);
    }
  } finally {
    await revokeMigrationOwners(admin);
  }
  // PostgREST caches the schema; reload it after migrations.
  await owner`notify pgrst, 'reload schema'`;
  return pending.length;
}

export async function createOwner(apiUrl: string, serviceKey: string, email: string, password: string) {
  const response = await fetch(`${apiUrl}/auth/v1/admin/users`, {
    method: "POST",
    headers: { authorization: `Bearer ${serviceKey}`, apikey: serviceKey, "content-type": "application/json" },
    body: JSON.stringify({ email, password, email_confirm: true }),
    signal: AbortSignal.timeout(15_000),
  });
  const body = await response.json().catch(() => ({})) as { error_code?: string };
  if (!response.ok && body.error_code !== "email_exists") throw new Error(`Could not create the owner account: ${response.status} ${JSON.stringify(body)}`);
  return response.ok;
}

// Backups: a pg_dump custom-format dump of the whole postgres database plus copies of the Storage
// files and config.json (the secrets the data needs: JWT secret, bank token key, owner login).
//   <home>/backups/<timestamp>-<reason>/{database.dump, storage/, config.json, manifest.json}
import { existsSync } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import type { Config } from "./config";
import { pgProgram, type Cluster } from "./postgres";
import { mustRun } from "./processes";

export type BackupManifest = {
  format: 1;
  createdAt: string;
  reason: string;
  automatic: boolean;
  appVersion?: string;
  schemaVersion?: string;
  services?: Record<string, string>;
  postgres: string;
  files: { database: string; storage: string; config: string };
};

export const AUTOMATIC_BACKUPS_KEPT = 5;

const folderName = (reason: string) =>
  `${new Date().toISOString().replace(/\.\d+Z$/, "Z").replaceAll(":", "-")}-${reason.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "backup"}`;

export async function writeBackup(options: { backups: string; storage: string; config: Config; configFile: string; cluster: Cluster; reason: string; automatic: boolean; postgresVersion: string }) {
  const { backups, cluster, reason } = options;
  await fs.mkdir(backups, { recursive: true });
  let folder = path.join(backups, folderName(reason));
  for (let n = 2; existsSync(folder); n++) folder = path.join(backups, `${folderName(reason)}-${n}`);
  const partial = `${folder}.partial`;
  await fs.mkdir(partial, { recursive: true });
  try {
    await mustRun(pgProgram(cluster, "pg_dump"), ["-h", "127.0.0.1", "-p", String(cluster.port), "-U", "supabase_admin", "-d", "postgres",
      "-Fc", "-f", path.join(partial, "database.dump")], { env: { ...process.env, PGPASSWORD: cluster.password }, timeoutMs: 30 * 60_000 });
    if (existsSync(options.storage)) await fs.cp(options.storage, path.join(partial, "storage"), { recursive: true });
    else await fs.mkdir(path.join(partial, "storage"));
    await fs.copyFile(options.configFile, path.join(partial, "config.json"));
    await fs.chmod(path.join(partial, "config.json"), 0o600);
    const manifest: BackupManifest = {
      format: 1, createdAt: new Date().toISOString(), reason, automatic: options.automatic,
      appVersion: options.config.appVersion, schemaVersion: options.config.schemaVersion, services: options.config.services,
      postgres: options.postgresVersion, files: { database: "database.dump", storage: "storage", config: "config.json" },
    };
    await fs.writeFile(path.join(partial, "manifest.json"), `${JSON.stringify(manifest, null, 2)}\n`);
    await fs.rename(partial, folder);
  } catch (error) {
    await fs.rm(partial, { recursive: true, force: true });
    throw error;
  }
  if (options.automatic) await pruneAutomatic(backups, AUTOMATIC_BACKUPS_KEPT);
  return folder;
}

// Keeps the newest `keep` automatic backups; backups the owner made are never removed.
async function pruneAutomatic(backups: string, keep: number) {
  const automatic: string[] = [];
  for (const entry of (await fs.readdir(backups)).sort().reverse()) {
    const manifest = await readManifest(path.join(backups, entry)).catch(() => undefined);
    if (manifest?.automatic) automatic.push(entry);
  }
  for (const entry of automatic.slice(keep)) await fs.rm(path.join(backups, entry), { recursive: true, force: true });
}

export async function readManifest(folder: string): Promise<BackupManifest> {
  const manifest = JSON.parse(await fs.readFile(path.join(folder, "manifest.json"), "utf8")) as BackupManifest;
  if (manifest.format !== 1) throw new Error(`${folder} is not a Moneo Desktop backup`);
  for (const file of [manifest.files.database, manifest.files.config])
    if (!existsSync(path.join(folder, file))) throw new Error(`${folder} is incomplete: ${file} is missing`);
  return manifest;
}

export async function restoreDump(cluster: Cluster, dump: string) {
  // One transaction: a failed restore leaves the fresh cluster empty instead of half-filled.
  await mustRun(pgProgram(cluster, "pg_restore"), ["-h", "127.0.0.1", "-p", String(cluster.port), "-U", "supabase_admin", "-d", "postgres",
    "--exit-on-error", "--single-transaction", dump], { env: { ...process.env, PGPASSWORD: cluster.password }, timeoutMs: 60 * 60_000 });
}

