import fs from "node:fs";
import path from "node:path";
const root = process.argv[2];
const found = new Map();
const sizes = new Map();
function walk(dir, pkg) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) {
      let next = pkg;
      if (path.basename(dir) === "node_modules") next = e.name.startsWith("@") ? null : e.name;
      else if (pkg === null) next = `${path.basename(dir)}/${e.name}`;
      walk(p, next);
    } else {
      const s = fs.statSync(p).size;
      if (pkg) sizes.set(pkg, (sizes.get(pkg) ?? 0) + s);
      if (e.name === "binding.gyp" || e.name.endsWith(".node")) found.set(pkg, (found.get(pkg) ?? 0) + 1);
    }
  }
}
