import { readFileSync, writeFileSync } from "node:fs";
const file = process.argv[2];
const text = readFileSync(file, "utf8");
const parts = text.split(/\n(?=--\n-- (?:Name|Data for Name): )/);
const moved = [];
const kept = parts.filter(part => {
  const header = part.match(/^--\n-- (?:Data for )?Name: ([^\n]*)/)?.[1] ?? "";
  if (/uuid-ossp|FUNCTION uuid_(generate|nil|ns)/.test(header)) { moved.push(part); return false; }
  return true;
});
const statements = moved.join("\n").split("\n").filter(line => /^(CREATE EXTENSION|COMMENT ON EXTENSION|GRANT )/.test(line));
const block = `
--
-- uuid-ossp, only where the bundled PostgreSQL has it: the Windows build has no uuid-ossp. Nothing
-- in Moneo, GoTrue or Storage uses it (they use gen_random_uuid()).
--

DO $moneo$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_available_extensions WHERE name = 'uuid-ossp') THEN
${statements.map(line => `    ${line}`).join("\n")}
  END IF;
END
$moneo$;
`;
const insertAt = kept.findIndex(part => /^--\n-- Data for Name: schema_migrations/.test(part));
kept.splice(insertAt, 0, block);
writeFileSync(file, kept.join("\n"));
console.log(`moved ${statements.length} statements`);

