// Runs each supabase/tests/*.sql regression on its own, rolled back, against SUPABASE_DB_URL
// (the upgrade-path step of supabase/tests/migrations.mjs, one file at a time).
// cwd must contain .env.qa (pointing at the database under test) and a `supabase` link to the repo's.
import { readFileSync, readdirSync } from "node:fs";
import { createRequire } from "node:module";
const repo = process.argv[2];
const require = createRequire(`${repo}/package.json`);
const postgres = (await import(require.resolve("postgres"))).default;
const { runIsolatedFixture } = await import(`file:///${repo}/supabase/tests/migration-replay.mjs`);
process.loadEnvFile(".env.qa");
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {}, connection: { lock_timeout: "10s", statement_timeout: "120s" } });
const rollback = new Error("rollback");
let failed = 0;
for (const file of readdirSync("supabase/tests").filter(name => name.endsWith(".sql")).sort()) {
  const sql = readFileSync(`supabase/tests/${file}`, "utf8");
  const started = Date.now();
  try {
    await db.begin(async tx => { await runIsolatedFixture(tx, file, sql); throw rollback; });
  } catch (error) {
    if (error !== rollback) { failed++; console.log(`FAIL ${file}: ${error.message.split("\n")[0]}`); continue; }
  }
  console.log(`PASS ${file} (${Date.now() - started} ms)`);
}
await db.end();
console.log(failed ? `${failed} file(s) failed` : "all SQL regressions passed");
process.exit(failed ? 1 : 0);

