// 1) dylib paths referenced by the macOS PostgREST binaries; 2) pruned PostgreSQL size per platform
// estimated from the archive listing with fetch-backend.mjs's prune rules.
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
const [build, downloads] = process.argv.slice(2);
for (const p of ["mac-arm64", "mac-x64"]) {
  const text = readFileSync(`${build}/${p}/postgrest/postgrest`).toString("latin1");
  console.log(p, [...new Set(text.match(/[@/][\w@./+-]*\.dylib/g))].join(" "));
}
const programs = new Set(["postgres", "initdb", "pg_ctl", "pg_dump", "pg_dumpall", "pg_restore", "psql", "pg_isready", "pg_controldata", "pg_resetwal", "pg_upgrade", "pg_checksums"]);
for (const [p, t, win] of [["win-x64", "x86_64-pc-windows-msvc", true], ["mac-arm64", "aarch64-apple-darwin"], ["mac-x64", "x86_64-apple-darwin"], ["linux-x64", "x86_64-unknown-linux-gnu"]]) {
  const listing = execFileSync("C:\\Windows\\System32\\tar.exe", ["-tvzf", `${downloads}/postgresql-17.11.1-${t}.tar.gz`], { maxBuffer: 1 << 28 }).toString();
  let total = 0, kept = 0;
  for (const line of listing.split("\n")) {
    const parts = line.trim().split(/\s+/);
    if (parts.length < 9 || line.startsWith("d")) continue;
    const size = Number(parts[4]); const rel = parts.slice(8).join(" ").split(" -> ")[0].split("/").slice(1);
    total += size;
    const [top, entry] = rel;
    if (top === "include" || (top === "share" && entry === "doc")) continue;
    if (top === "bin") {
      const base = entry.replace(/\.exe$/i, "");
      const program = win ? entry.toLowerCase().endsWith(".exe") : true;
      if ((program && !programs.has(base)) || /python|^DLLs$|^Lib$/i.test(entry)) continue;
    }
    if (top === "lib" && /\.(a|lib)$|^pgxs$|^pkgconfig$|python|^llvmjit|^bitcode$|libLLVM/i.test(entry)) continue;
    kept += size;
  }
  console.log(`${p}: archive contents ${(total / 1048576).toFixed(1)} MB, after prune ${(kept / 1048576).toFixed(1)} MB`);
}

