// Prints the DLL imports of PE files that are not bundled next to them and not core Windows DLLs.
import { readFileSync, readdirSync } from "node:fs";
import path from "node:path";
function imports(file) {
  const b = readFileSync(file);
  const pe = b.readUInt32LE(0x3c);
  const sections = b.readUInt16LE(pe + 6), optSize = b.readUInt16LE(pe + 20), opt = pe + 24;
  const magic = b.readUInt16LE(opt);
  const dirs = opt + (magic === 0x20b ? 112 : 96);
  const importRva = b.readUInt32LE(dirs + 8);
  const secs = [];
  for (let i = 0; i < sections; i++) {
    const s = opt + optSize + i * 40;
    secs.push({ va: b.readUInt32LE(s + 12), size: b.readUInt32LE(s + 8), raw: b.readUInt32LE(s + 20) });
  }
  const off = rva => { const s = secs.find(s => rva >= s.va && rva < s.va + Math.max(s.size, 1)); return s ? rva - s.va + s.raw : -1; };
  const names = [];
  if (!importRva) return names;
  for (let d = off(importRva); ; d += 20) {
    const nameRva = b.readUInt32LE(d + 12);
    if (!nameRva) break;
    const o = off(nameRva);
    names.push(b.toString("latin1", o, b.indexOf(0, o)).toLowerCase());
  }
  return names;
}
for (const dir of process.argv.slice(2)) {
  const local = new Set(readdirSync(dir).map(f => f.toLowerCase()));
  const extra = new Set();
  for (const f of readdirSync(dir).filter(f => /\.(exe|dll)$/i.test(f))) {
    for (const name of imports(path.join(dir, f))) if (!local.has(name) && !/^(api-ms-win-core|kernel32|user32|advapi32|ws2_32|secur32|shell32|ole32|oleaut32|crypt32|bcrypt|ntdll|shlwapi|wldap32|netapi32|iphlpapi|userenv|dbghelp|psapi|winmm|gdi32|rpcrt4|normaliz|mswsock|dnsapi|version|powrprof|setupapi|comdlg32|winhttp|ncrypt|cfgmgr32|propsys|wintrust|imm32|comctl32|msvcrt)\.dll$/.test(name)) extra.add(name);
  }
  console.log(dir, [...extra].sort().join(" "));
}
